package com.example.familymenu.category.repository;
import com.example.familymenu.category.domain.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository; import java.util.*; import java.util.concurrent.atomic.AtomicLong;
@Repository @Profile("memory") public class InMemoryCategoryRepository implements CategoryRepository {private final Map<Long,DishCategory> data=new HashMap<>();private final AtomicLong seq=new AtomicLong(); public InMemoryCategoryRepository(){save(new DishCategory(null,"家常菜",1,true));save(new DishCategory(null,"汤",2,true));} public List<DishCategory> findAll(boolean all){List<DishCategory>x=new ArrayList<>(data.values());if(!all)x.removeIf(c->!c.isEnabled());x.sort(Comparator.comparingInt(DishCategory::getSort).thenComparing(DishCategory::getId));return x;}public Optional<DishCategory> findById(Long id){return Optional.ofNullable(data.get(id));}public Optional<DishCategory> findByName(String n){return data.values().stream().filter(c->c.getName().equals(n)).findFirst();}public DishCategory save(DishCategory c){long id=c.getId()==null?seq.incrementAndGet():c.getId();DishCategory x=new DishCategory(id,c.getName(),c.getSort(),c.isEnabled());data.put(id,x);return x;}public boolean deleteById(Long id){return data.remove(id)!=null;}}
